if(k==0)return num(`How much more than ${a} is ${a+d}?`,d,`${a+d} − ${a} = ${d}.`);
if(k==1)return num(`How much less than ${a+d} is ${a}?`,d,`${a+d} − ${a} = ${d}.`);
if(k==2)return num(`${a} is ${d} less than what number?`,a+d,`${a} + ${d} = ${a+d}.`);
