const STORE={schema:3,legacyKey:'m3a2',configKey:'mg3a_supabase_config',sessionKey:'mg3a_auth_session',activeKey:'mg3a_active_user'};
const freshData=()=>({stars:0,hat:'',own:[],tp:{},err:{},best:0,snd:1,mode:'smart',level:'all',mistakes:[],reviewAt:{},reviewGap:{},sessions:[],lastStudy:'',speechRate:0.9,learningMode:'guided',skillEvidence:{},dailyGoal:10,dailyLearning:{},errorLog:[],schema:5});
const readJSON=(k,fb=null)=>{try{const v=localStorage.getItem(k);return v?JSON.parse(v):fb}catch(e){return fb}};
const normalizeData=x=>{const d={...freshData(),...(x||{})};d.own=Array.isArray(d.own)?d.own:[];d.tp=d.tp||{};d.err=d.err||{};d.skillEvidence=d.skillEvidence&&typeof d.skillEvidence==='object'?d.skillEvidence:{};d.dailyGoal=Math.min(30,Math.max(5,Number(d.dailyGoal)||10));d.mistakes=Array.isArray(d.mistakes)?d.mistakes:[];d.errorLog=Array.isArray(d.errorLog)?d.errorLog:[];d.dailyLearning=d.dailyLearning&&typeof d.dailyLearning==='object'&&!Array.isArray(d.dailyLearning)?d.dailyLearning:{};d.reviewAt=d.reviewAt||{};d.reviewGap=d.reviewGap||{};d.sessions=Array.isArray(d.sessions)?d.sessions:[];d.mode=d.mode||'smart';d.level=d.level||'all';d.speechRate=Number.isFinite(+d.speechRate)?Math.min(1.2,Math.max(.7,+d.speechRate)):.9;d.learningMode=d.learningMode||'guided';d.schema=5;return d};
let AUTH={session:readJSON(STORE.sessionKey),config:readJSON(STORE.configKey,{url:'',key:''}),user:null,syncTimer:null,syncing:false,lastSync:'',error:''};
const activeUser=()=>readJSON(STORE.activeKey,null);
if(AUTH.session?.user?.id&&!activeUser())localStorage.setItem(STORE.activeKey,JSON.stringify({id:AUTH.session.user.id,email:AUTH.session.user.email}));
const dataKey=()=>activeUser()?`m3a2_user_${activeUser().id}`:STORE.legacyKey;
let D=normalizeData(readJSON(dataKey(),activeUser()?freshData():readJSON(STORE.legacyKey,{})));
function save(){D=normalizeData(D);try{localStorage.setItem(dataKey(),JSON.stringify(D));if(activeUser())localStorage.setItem(`m3a2_user_${activeUser().id}`,JSON.stringify(D));}catch(e){console.warn('Progress could not be saved locally',e)}if(AUTH.session&&AUTH.config.url&&AUTH.config.key)scheduleCloudSync();}
function sbHeaders(token){return {'apikey':AUTH.config.key,'Authorization':'Bearer '+(token||AUTH.config.key),'Content-Type':'application/json'}}
async function sbRequest(path,opts={}){if(!AUTH.config.url||!AUTH.config.key)throw Error('Please configure Supabase URL and anon key first.');const r=await fetch(AUTH.config.url.replace(/\/$/,'')+path,{...opts,headers:{...sbHeaders(AUTH.session?.access_token),...(opts.headers||{})}});const t=await r.text();let j=null;try{j=t?JSON.parse(t):null}catch{}if(!r.ok)throw Error(j?.msg||j?.message||j?.error_description||t||`Request failed (${r.status})`);return j}
async function refreshAuth(){if(!AUTH.session?.refresh_token)return false;const r=await fetch(AUTH.config.url.replace(/\/$/,'')+'/auth/v1/token?grant_type=refresh_token',{method:'POST',headers:{apikey:AUTH.config.key,'Content-Type':'application/json'},body:JSON.stringify({refresh_token:AUTH.session.refresh_token})});const j=await r.json();if(!r.ok)throw Error(j.msg||j.message||'Session refresh failed');AUTH.session={...j,expires_at:Date.now()+((j.expires_in||3600)*1000)};localStorage.setItem(STORE.sessionKey,JSON.stringify(AUTH.session));return true}
async function ensureSession(){if(!AUTH.session)return false;if(AUTH.session.expires_at&&AUTH.session.expires_at<Date.now()+60000)await refreshAuth();return !!AUTH.session?.access_token}
async function cloudLoad(){await ensureSession();const uid=AUTH.session.user.id;const rows=await sbRequest(`/rest/v1/student_progress?select=payload&user_id=eq.${encodeURIComponent(uid)}&limit=1`);return rows?.[0]?.payload||null}
async function cloudSave(){if(!AUTH.session||AUTH.syncing)return;AUTH.syncing=true;try{await ensureSession();const uid=AUTH.session.user.id;await sbRequest('/rest/v1/student_progress?on_conflict=user_id',{method:'POST',headers:{Prefer:'resolution=merge-duplicates,return=minimal'},body:JSON.stringify({user_id:uid,payload:D,updated_at:new Date().toISOString()})});AUTH.lastSync=new Date().toISOString();AUTH.error=''}catch(e){AUTH.error=e.message;console.warn('Cloud sync pending:',e.message)}finally{AUTH.syncing=false}}
function scheduleCloudSync(){clearTimeout(AUTH.syncTimer);AUTH.syncTimer=setTimeout(cloudSave,900)}
const app=$('#app'),stars=n=>'★'.repeat(n)+'☆'.repeat(3-n),HATS=[['👑','Royal Crown',10],['🥳','Party Hat',15],['🧙‍♂️','Wizard Hat',20],['🎓','Grad Cap',25]];
